-- I dispositivi del cliente: apparecchi veri (con numero di serie) inseriti a mano, diversi dal
-- catalogo `device` dei report. Un contratto ne copre zero o più, un intervento di un contratto
-- ne indica al più uno fra quelli del contratto. Il testo libero `contract.device` sparisce: prima
-- di toglierlo lo si accoda alle note, così non si perde nei database di sviluppo (i contratti
-- non sono ancora in produzione).
CREATE TABLE IF NOT EXISTS "customer_device" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "customer_device_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"type" varchar(20) NOT NULL,
	"name" varchar(255) NOT NULL,
	"serial_number" varchar(255) NOT NULL,
	"model" varchar(255),
	"note" text,
	"updated_at" timestamp DEFAULT null,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"customer_id" integer NOT NULL,
	CONSTRAINT "customer_device_customer_id_id_unique" UNIQUE("customer_id","id"),
	CONSTRAINT "customer_device_type_check" CHECK ("customer_device"."type" IN ('pc_desktop', 'server', 'copier', 'firewall', 'cash_register'))
);--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "contract_device" (
	"contract_id" integer NOT NULL,
	"customer_device_id" integer NOT NULL,
	"customer_id" integer NOT NULL,
	CONSTRAINT "contract_device_contract_id_customer_device_id_pk" PRIMARY KEY("contract_id","customer_device_id")
);--> statement-breakpoint
ALTER TABLE "customer_device" ADD CONSTRAINT "customer_device_customer_id_customer_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."customer"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "contract_device" ADD CONSTRAINT "contract_device_contract_fk" FOREIGN KEY ("customer_id","contract_id") REFERENCES "public"."contract"("customer_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "contract_device" ADD CONSTRAINT "contract_device_customer_device_fk" FOREIGN KEY ("customer_id","customer_device_id") REFERENCES "public"."customer_device"("customer_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "customer_device_customer_id_idx" ON "customer_device" USING btree ("customer_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "customer_device_customer_serial_lower_idx" ON "customer_device" USING btree ("customer_id",lower("serial_number"));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "customer_device_name_trgm_idx" ON "customer_device" USING gin ("name" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "customer_device_serial_number_trgm_idx" ON "customer_device" USING gin ("serial_number" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "contract_device_customer_device_id_idx" ON "contract_device" USING btree ("customer_device_id");--> statement-breakpoint
ALTER TABLE "intervention" ADD COLUMN "customer_device_id" integer;--> statement-breakpoint
ALTER TABLE "intervention" ADD CONSTRAINT "intervention_customer_device_id_customer_device_id_fk" FOREIGN KEY ("customer_device_id") REFERENCES "public"."customer_device"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "intervention" ADD CONSTRAINT "intervention_contract_device_fk" FOREIGN KEY ("contract_id","customer_device_id") REFERENCES "public"."contract_device"("contract_id","customer_device_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "intervention" ADD CONSTRAINT "intervention_device_contract_check" CHECK ("intervention"."customer_device_id" IS NULL OR "intervention"."contract_id" IS NOT NULL);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "intervention_customer_device_id_idx" ON "intervention" USING btree ("customer_device_id");--> statement-breakpoint
-- Il testo del vecchio campo passa alle note (nessuna perdita di dati), poi la colonna si toglie.
